     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
            return null;
        }
        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
     *  100, rounded as its rounding policy has it, raised to the sheet's floor in force on its date (a correction's never is); null with no rate in force then. */
    private BigDecimal dueOf(Claim claim, Person person) {
        BigDecimal floor = sheets.floorOn(claim.getSheetId(), claim.getDate());
        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
                .map(due -> claim.isCorrection() ? due : due.max(floor))
                .orElse(null);
    }

    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
     *  correction the date of the claim it corrects. */
    private RoundingMode roundingOf(Claim claim) {
        LocalDate on = claim.getCorrects() == null ? claim.getDate()
                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
                        .map(Claim::getDate).orElse(claim.getDate());
        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
    }

    private void record(String event, String user, Person person, Claim claim) {
        record(event, user, person, claim, claim.getNumber());
    }

    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
    private void record(String event, String user, Person person, Claim claim, String number) {
        record(event, user, person, claim, number, "");
    }

    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
    }

    /** Notify each user watching the person that one of their claims was settled, in the order
     *  they started watching. */
    private void notifyWatchers(String user, Person person, String number) {
        for (PersonWatch w : watches.findByPersonIdOrderByIdAsc(person.getId())) {
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The rate was changed at the same moment; try again.';
  return otherError(e);
}

/** Whole cents times a percent (in hundredths of a percent), divided by 100, in whole cents,
 *  rounded half to even, or half up when `halfUp` (a negative product rounded as its size is).
 *  Worked in BigInt so large amounts stay exact. */
export function dueCents(cents: number, pctHundredths: number, halfUp = false): number {
  const product = BigInt(cents) * BigInt(pctHundredths);
  const size = product < 0n ? -product : product;
  const whole = size / 10000n;
  const rest = size % 10000n;
  const rounded = rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
  return Number(product < 0n ? -rounded : rounded);
}

/** What a claim's late charge follows: the sheet's today and the late percent in force on each boundary date. */
export interface Lateness {
  today: string | null;
  /** The late percent with two decimals in force on a date. */
  latePctOn: (date: string) => string;
}

/** A claim's due in cents: the due fixed when it was settled, else its figure (the due a statement
 *  bound it to (unless PENDING), else its amount times its grade's rate in force on its date, rounded half up when
 *  `halfUp` (the claim's rounding policy) else half to even, and raised to the sheet's floor in force on its date) with
 *  its late charge, rounded the same way, on top (a correction is neither raised to the floor nor
 *  charged late); null (n/a) with no figure. */
export function claimDueCents(rates: readonly Rate[], c: Claim, floorCents: number, late: Lateness, halfUp: boolean): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  const figure = figureCents(rates, c, floorCents, halfUp);
  return figure === null ? null : figure + lateChargeCents(c, figure, late, halfUp);
}

function figureCents(rates: readonly Rate[], c: Claim, floorCents: number, halfUp: boolean): number | null {
  if (isBound(c)) return c.statedDue === null ? null : cents(c.statedDue);
  const pct = pctOn(rates, c.date);
  if (pct === null) return null;
  const due = dueCents(cents(c.amount), cents(pct), halfUp);
  return isCorrection(c) ? due : Math.max(due, floorCents);
}

/** An overdue claim's late charge in cents: for every full 30 days past its due-by, the late percent
 *  in force on that boundary date (the due-by plus 30, 60, 90 ... days) of its figure, each rounded by
 *  the claim's rounding policy, added up; 0 when it is not overdue. */
function lateChargeCents(c: Claim, figure: number, late: Lateness, halfUp: boolean): number {
  if (late.today === null || isCorrection(c) || !overdue(c, late.today)) return 0;
  const days = Math.round((Date.parse(late.today) - Date.parse(dueBy(c))) / 86_400_000);
  let charge = 0;
  for (let step = 1; step <= Math.floor(days / 30); step++) {
    const pct = cents(late.latePctOn(plusDays(dueBy(c), step * 30)));
    if (pct !== 0) charge += dueCents(figure, pct, halfUp);
  }
  return charge;
}

/** A date (yyyy-mm-dd) moved on by whole days. */
function plusDays(date: string, days: number): string {
  return new Date(Date.parse(date) + days * 86_400_000).toISOString().slice(0, 10);
}

